export function plausibleSecret(v: string): boolean {
  if (v.length < 8 || v.length > 256 || /\s/.test(v) || UUID.test(v) || isReference(v)) return false
  const symbol = /[^A-Za-z0-9]/.test(v)
  const digit = /\d/.test(v)
