const CHECKS: Readonly<Record<string, (m: RegExpMatchArray) => boolean>> = {
  'bearer token': m => !isReference(m[1] ?? ''),
  'database url with credentials': m => urlCredential(m[0]),
  'database url with password': m => urlCredential(m[0]),
